import{_ as d,o as e,c as a,ai as r}from"./chunks/framework.XEs52zTF.js";const m=JSON.parse('{"title":"学习路线","description":"","frontmatter":{"title":"学习路线"},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md"}'),o={name:"roadmap.md"};function l(i,t,h,c,n,p){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="学习路线-让每一步都有产物" tabindex="-1">学习路线：让每一步都有产物 <a class="header-anchor" href="#学习路线-让每一步都有产物" aria-label="Permalink to &quot;学习路线：让每一步都有产物&quot;">​</a></h1><p>不要用“读完多少页”判断掌握程度。更可靠的标准是：你能否解释一个输入为何得到这个输出，能否添加一个测试证明自己的修改。以下时间仅供安排，遇到不熟悉的 C++ 或数据结构时可以多停留。</p><h2 id="路线一-第一次接触编译原理" tabindex="-1">路线一：第一次接触编译原理 <a class="header-anchor" href="#路线一-第一次接触编译原理" aria-label="Permalink to &quot;路线一：第一次接触编译原理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>阅读</th><th>动手产物</th><th>验收</th></tr></thead><tbody><tr><td>准备，约 1–2 周</td><td>第 1–3 章</td><td>构建 Sprout，跑通示例，学会读错误</td><td>独立修改程序并重新运行</td></tr><tr><td>定义规则，约 1 周</td><td>第 4–6 章</td><td>写出语言规范、Token 表、一个 NFA 到 DFA 的推导</td><td>解释 <code>&gt;=</code> 为什么不能切成两个 Token</td></tr><tr><td>构造前端，约 2–3 周</td><td>第 7–10 章</td><td>解析表达式、作用域与类型检查</td><td>对错误程序给出位置与原因</td></tr><tr><td>完成闭环，约 2 周</td><td>第 11–12 章</td><td>AST → 字节码 → VM，运行递归</td><td><code>fib(10)</code> 输出 55；短路避免除零</td></tr><tr><td>解释中间层，约 2–3 周</td><td>第 13–16 章</td><td>画 CFG、手算数据流和 SSA，添加一个优化</td><td>优化前后程序结果一致</td></tr><tr><td>走向本机，约 2–3 周</td><td>第 17–19 章</td><td>构建生成的 C++，解释 ABI，试写 LLVM IR</td><td>说明每一层由谁完成</td></tr><tr><td>完成工程，持续练习</td><td>第 20–22 章</td><td>添加一项语言特性和完整回归测试</td><td>提交规范、实现、测试与限制说明</td></tr></tbody></table><p>若你还不会编程，请先完成第 2 章的容器、函数、对象和所有权小练习。编译器是很好的练习项目，但同时学习语法、内存和编译理论会增加认知负担。每次只引入一个新的困难。</p><h2 id="路线二-已经会-c-想快速建立全景" tabindex="-1">路线二：已经会 C++，想快速建立全景 <a class="header-anchor" href="#路线二-已经会-c-想快速建立全景" aria-label="Permalink to &quot;路线二：已经会 C++，想快速建立全景&quot;">​</a></h2><p>先读第 1、4 章，运行配套代码；按 <code>--tokens</code>、<code>--ast</code>、<code>--check</code>、<code>--bytecode</code>、默认执行的顺序观察同一个输入。阅读第 5、7、10、11、12 章完成主线，然后补第 6、8 章的形式理论。不要用“看过一个输出”代替自己实现；最少选一个阶段重新写一次。</p><h2 id="第一次的-90-分钟实验" tabindex="-1">第一次的 90 分钟实验 <a class="header-anchor" href="#第一次的-90-分钟实验" aria-label="Permalink to &quot;第一次的 90 分钟实验&quot;">​</a></h2><ol><li>下载<a href="./source.html">配套源码</a>，确认终端中 <code>g++ --version</code> 能输出版本。</li><li>构建编译器并运行 <code>compiler/examples/hello.spr</code>。</li><li>把输出表达式改成 <code>2 + 3 * 4</code>，先预测，再运行。</li><li>打开<a href="./lab.html">交互实验室</a>，比较 <code>2 + 3 * 4</code> 和 <code>(2 + 3) * 4</code> 的树与指令。</li><li>故意漏写分号、引用不存在的名字、令整数除以零。分别记录错误发生在哪个阶段。</li><li>为刚才发现的一个边界条件写下“输入、预期、实际、结论”。</li></ol><p>这次实验的目标是建立地图。自动机、LR、SSA 都会在后面推导，不要求在第一次运行之前掌握。</p><h2 id="如何真正从零实现" tabindex="-1">如何真正从零实现 <a class="header-anchor" href="#如何真正从零实现" aria-label="Permalink to &quot;如何真正从零实现&quot;">​</a></h2><p>配套的 <code>compiler/</code> 是可运行参考答案。只复制完整文件能得到可执行程序，却不能替代构造过程。建议另建 <code>my-sprout/</code>，按以下顺序写代码，每一步都保留测试：</p><ol><li>接收一个整数并输出；不要先设计所有类。</li><li>扫描整数、符号与位置，打印 Token；此时还没有 Parser。</li><li>支持括号与四则运算，先生成 AST，再输出树。</li><li>把 AST 编译成 <code>PUSH/ADD/MUL</code>，写一个十几行的栈机。</li><li>添加局部变量、符号表、类型检查，先拒绝非法程序。</li><li>添加 <code>if</code> 和 <code>while</code>，学会跳转回填与栈高度核对。</li><li>添加函数签名、参数、本地槽位、调用帧、返回值，最后加入递归。</li><li>把每一步的错误样例变成回归测试，再尝试优化和第二后端。</li></ol><p>每个阶段的实作可以对照相应章的教学片段，但片段不承诺可直接替换参考实现的某一段。参考实现的对象布局和全部边界规则以 <a href="./source.html">源码导读</a>与 <code>compiler/SPEC.md</code> 为准。</p><h2 id="主线实现与扩展实验的边界" tabindex="-1">主线实现与扩展实验的边界 <a class="header-anchor" href="#主线实现与扩展实验的边界" aria-label="Permalink to &quot;主线实现与扩展实验的边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>随书编译器</th><th>学习目标</th></tr></thead><tbody><tr><td>Lexer、Parser、AST、静态语义</td><td>已实现</td><td>第 4–10 章</td></tr><tr><td>栈式字节码、跳转、调用帧、递归</td><td>已实现</td><td>第 11–12 章</td></tr><tr><td>生成独立 C++11 源码</td><td>已实现</td><td>第 17、20 章</td></tr><tr><td>直接发射汇编或目标文件</td><td>扩展实验</td><td>第 17–19 章</td></tr><tr><td>三地址 IR、SSA、优化 pass</td><td>扩展实验</td><td>第 13–16 章</td></tr><tr><td>LLVM 后端、RISC-V 后端</td><td>扩展实验</td><td>第 19 章</td></tr><tr><td>数组、字符串、闭包、GC、模块、JIT</td><td>扩展实验</td><td>第 18、22 章</td></tr></tbody></table><p>C++ 目标路径也是编译：Sprout 源语言被翻译为另一种语言，宿主 C++ 编译器再完成优化、机器码生成和链接。本书没有把宿主后端所做的工作算作 Sprout 已实现的机器后端。</p><h2 id="结业项目怎么选" tabindex="-1">结业项目怎么选 <a class="header-anchor" href="#结业项目怎么选" aria-label="Permalink to &quot;结业项目怎么选&quot;">​</a></h2><p>第一次推荐添加 <code>for</code> 循环，并把它降低为已有的 <code>while</code>，这样可以完整经历规范、词法、语法、作用域、控制流、测试六个环节。第二次再选择数组或 LLVM 后端，避免同时更改语言、内存模型和目标平台。</p><p>交付物应包含：新语法的 EBNF；至少三个成功示例；至少五个拒绝/运行错误示例；对求值顺序、类型与作用域的说明；测试运行命令；已知限制。能解释“为什么这个错误必须被拒绝”，比实现一长串未定义行为更有价值。</p><h2 id="遇到困难时怎样回退" tabindex="-1">遇到困难时怎样回退 <a class="header-anchor" href="#遇到困难时怎样回退" aria-label="Permalink to &quot;遇到困难时怎样回退&quot;">​</a></h2><ul><li>Parser 出错：先看 Token，不要立即怀疑文法算法。</li><li>语义检查出错：用最小作用域例子，先移除循环与函数。</li><li>VM 输出不对：观察字节码和每一步栈变化，核对跳转目的地。</li><li>递归出错：只调用一次恒等函数，再增加第二层调用。</li><li>优化出错：保存未优化输出，缩小到一个基本块，检查溢出与副作用。</li></ul><p>每章读完勾选“已完成”，并保留自己的实验记录。本站的进度保存在浏览器本地；更换设备不会同步。</p><h2 id="新增现代高级专题-ai-编译与学习式优化" tabindex="-1">新增现代高级专题：AI 编译与学习式优化 <a class="header-anchor" href="#新增现代高级专题-ai-编译与学习式优化" aria-label="Permalink to &quot;新增现代高级专题：AI 编译与学习式优化&quot;">​</a></h2><p>前面 22 章的学习顺序和内容保持不变。完成控制流、IR、优化和后端基础后，可继续以下三章；如果还未学过矩阵乘与张量，先完成第 24 章的最小 Python 实验。</p><ul><li><a href="./chapter23.html">第 23 章：AI 编译链</a>：模型捕获、图 IR、形状与类型、算子降低与部署。</li><li><a href="./chapter24.html">第 24 章：AI 编译器与张量调度</a>：融合、分块、布局、并行与异构执行。</li><li><a href="./chapter25.html">第 25 章：AI 辅助优化与验证</a>：自动调优、学习式代价模型、MLGO 和结果验证。</li><li><a href="./tensor-lab.html">张量分块实验室</a>：单步观察矩阵乘小块累加，区分理想访存模型与实测性能。</li></ul><p>这些专题使用独立小实验与官方工具拓展，不会把 Sprout 参考实现描述为已经具备 AI 后端。</p>',27)])])}const u=d(o,[["render",l]]);export{m as __pageData,u as default};
